-- CARDORA STORAGE DRAFT — DO NOT APPLY TO LIVE DATABASE.
-- Purpose: private, immutable seller-submitted images in a dedicated bucket.
-- Verified 2026-11-22: canonical Cardora project has zero storage buckets
-- and zero storage.objects policies. This script is for an isolated staging DB.
-- Must obtain snapshot, test with 2 distinct sellers + admin before any production use.
-- This SQL does not expose a public URL or enable listing publication.
--
-- Expected object key (generated by trusted app logic AFTER seller approval):
--   <auth.users.id>/<listing-uuid>/<front|back>.<jpg|png|webp>
-- Object names are never taken from the client's original filename.
-- Supabase Storage validates bucket MIME + file-size limit. Magic-byte validation,
-- malware scanning, stripping EXIF and moderation must be performed separately.
-- Admin reviewing images needs a dedicated authenticated server endpoint that
-- rechecks active admin role; do NOT grant anon read or public bucket access.
--
-- Stop if the bucket already exists; review existing settings before updating.
do $$
begin
  if exists (select 1 from storage.buckets where id='cardora-listing-evidence') then
    raise exception 'CARDORA_BUCKET_ALREADY_EXISTS_REVIEW_REQUIRED';
  end if;
end $$;
insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
values ('cardora-listing-evidence','cardora-listing-evidence',false,10485760,
        array['image/jpeg','image/png','image/webp']);

-- Fail-closed ownership predicate:
-- (1) actual, nonanonymous authenticated subject
-- (2) first path component is that subject's auth UUID
-- (3) valid strict three-component path and front/back basename
-- (4) profile active, linked seller approved
-- (5) no browser-supplied seller_id can bypass the auth link.
-- Note: create_seller_listing RPC must separately verify the listing belongs
-- to this seller BEFORE a future upload flow is enabled. That ownership check
-- is NOT implemented here; storage write must remain disabled until then.
--
-- Stage 1 policy is read-only owner preview. NO INSERT/UPDATE/DELETE POLICY.
-- This deliberately cannot be used to upload yet. A separate tested server
-- operation will validate listing status, identity, file contents and paths.
create policy cardora_evidence_owner_select
on storage.objects for select to authenticated
using (
  bucket_id='cardora-listing-evidence'
  and (select auth.uid()) is not null
  and (storage.foldername(name))[1]=(select auth.uid())::text
  and exists (
    select 1 from public.users u
    where u.auth_user_id=(select auth.uid())
      and u.status='active'
      and exists (
        select 1 from public.seller_profiles sp
        where sp.user_id=u.id and sp.status='approved'
      )
  )
);

-- Explicitly do NOT create INSERT/UPDATE/DELETE policies here.
-- Secure upload requirements:
-- 1. Server-side authenticated upload authorization tied to a PENDING listing
--    owned by caller's approved seller_profile; reject another seller's UUID.
-- 2. Two expected object keys (front/back), MIME allowlist, real content sniff,
--    per-user quota and rate limiting. No overwrite (upsert=false).
-- 3. Document the evidence path on listing metadata via trusted transactional API.
-- 4. Private download via short-lived signed URLs only after admin authorization;
--    never show private evidence publicly.
-- 5. Roll back partial uploads, handle orphan cleanup and disputes safely.
-- 6. Verify all policies as guest, Seller A, Seller B, inactive seller and admin.
